// Define the possible hook strings here so we can get the length
#define HOOK_ACTIVATE "ACTIVATE"
#define HOOK_DEACTIVATE "DEACTIVATE"

#define HOOK_CMD_MAX (sizeof(DEVICEHOOKPATH) + GPS_PATH_MAX \
                      + sizeof(HOOK_DEACTIVATE))

static void gpsd_run_device_hook(struct gpsd_errout_t *errout,
                                 char *device_name, char *hook)
{
    struct stat statbuf;
    int status;
    char buf[HOOK_CMD_MAX];

    if (-1 == stat(DEVICEHOOKPATH, &statbuf)) {
        GPSD_LOG(LOG_PROG, errout,
                 "CORE: no %s present, skipped running %s hook. %s(%d)\n",
                 DEVICEHOOKPATH, hook, strerror(errno), errno);
        return;
    }

    (void)snprintf(buf, sizeof(buf), "%s %s %s",
                   DEVICEHOOKPATH, device_name, hook);
    GPSD_LOG(LOG_INF, errout, "CORE: running %s\n", buf);
    status = system(buf);
    if (-1 == status) {
        GPSD_LOG(LOG_ERROR, errout, "CORE: error %s(%d) running %s\n",
                 strerror(errno), errno, buf);
    } else {
        GPSD_LOG(LOG_INF, errout,
                 "CORE: %s returned %d\n", DEVICEHOOKPATH,
                 WEXITSTATUS(status));
    }
}

int gpsd_switch_driver(struct gps_device_t *session, char *type_name)
{
    const struct gps_type_t **dp;
    bool first_sync = (NULL != session->device_type);
    unsigned int i;

    if (first_sync &&
        0 == strcmp(session->device_type->type_name, type_name)) {
        // no need to switch driver
        return 0;
    }

    GPSD_LOG(LOG_PROG, &session->context->errout,
             "CORE: switch_driver(%s) called...\n", type_name);
    for (dp = gpsd_drivers, i = 0; *dp; dp++, i++)
        if (0 == strcmp((*dp)->type_name, type_name)) {
            GPSD_LOG(LOG_PROG, &session->context->errout,
                     "CORE: selecting %s driver...\n",
                     (*dp)->type_name);
            gpsd_assert_sync(session);
            session->device_type = *dp;

        lexer->length = 0;
        return character_pushback(lexer, GROUND_STATE);
    }
    return true;        // no pushback
}

// packet grab succeeded, move to output buffer
static void packet_accept(struct gps_lexer_t *lexer, int packet_type)
{
    size_t packetlen = lexer->inbufptr - lexer->inbuffer;

    if (sizeof(lexer->outbuffer) > packetlen) {
        char scratchbuf[MAX_PACKET_LENGTH * 4 + 1];

        memcpy(lexer->outbuffer, lexer->inbuffer, packetlen);
        lexer->outbuflen = packetlen;
        lexer->outbuffer[packetlen] = '\0';
        lexer->type = packet_type;
        GPSD_LOG(LOG_RAW1, &lexer->errout,
                 "Packet type %d accepted %zu = %s\n",
                 packet_type, packetlen,
                 gpsd_packetdump(scratchbuf,  sizeof(scratchbuf),
                                 lexer->outbuffer,
                                 lexer->outbuflen));
    } else {
        GPSD_LOG(LOG_ERROR, &lexer->errout,
                 "Rejected too long packet type %d len %zu\n",
                 packet_type, packetlen);
    }
}

// shift the input buffer to discard all data up to current input pointer
static void packet_discard(struct gps_lexer_t *lexer)
{
    size_t discard = lexer->inbufptr - lexer->inbuffer;
    size_t remaining = lexer->inbuflen - discard;
    char scratchbuf[MAX_PACKET_LENGTH * 4 + 1];

    if (sizeof(lexer->inbuffer) < discard) {
        // Huh?
        GPSD_LOG(LOG_WARN, &lexer->errout,
                 "packet_discard() of %zu??\n", discard);
        lexer->inbufptr = lexer->inbuffer;
        lexer->inbuflen = 0;
        return;
    }  // else

    lexer->inbufptr = memmove(lexer->inbuffer, lexer->inbufptr, remaining);
    lexer->inbuflen = remaining;

    GPSD_LOG(LOG_RAW1, &lexer->errout,
             "packet_discard() of %zu, chars remaining is %zu = %s\n",
             discard, remaining,
             gpsd_packetdump(scratchbuf, sizeof(scratchbuf),
                             lexer->inbuffer, lexer->inbuflen));
}

