    pdop = sqrt(inv[0][0] + inv[1][1] + inv[2][2]);
    tdop = sqrt(inv[3][3]);
    gdop = sqrt(inv[0][0] + inv[1][1] + inv[2][2] + inv[3][3]);

    GPSD_LOG(LOG_DATA, errout,
             "CORE: DOPS computed/reported: X=%f/%f Y=%f/%f H=%f/%f "
             "V=%f/%f P=%f/%f T=%f/%f G=%f/%f\n",
