    }
    if (0 == isfinite(dop->ydop)) {
        dop->ydop = ydop;
    }
    if (0 == isfinite(dop->hdop)) {
        dop->hdop = hdop;
    }
    if (0 == isfinite(dop->vdop)) {
        dop->vdop = vdop;
    }
    if (0 == isfinite(dop->pdop)) {
        dop->pdop = pdop;
    }
    if (0 == isfinite(dop->tdop)) {
        dop->tdop = tdop;
    }
    if (0 == isfinite(dop->gdop)) {
        dop->gdop = gdop;
    }

    return DOP_SET;
}

